import {parseCommand} from './core.js';
export class Voice{
 constructor({notify,command,context,onText}){Object.assign(this,{notify,command,context,onText});this.lastText='';this.listening=false;this.connected=false;this.questions=0}
 text(t){this.lastText=t;this.onText(t)}
 speak(t){this.stopListening();speechSynthesis.cancel();this.text(t);const u=new SpeechSynthesisUtterance(t);u.lang='fr-FR';u.rate=.97;u.voice=speechSynthesis.getVoices().find(v=>v.name===this.voiceName)||speechSynthesis.getVoices().find(v=>v.lang==='fr-FR')||null;speechSynthesis.speak(u)}
 stop(){speechSynthesis.cancel();this.stopListening();if(this.dc?.readyState==='open'){this.send({type:'response.cancel'});this.send({type:'output_audio_buffer.clear'})}if(this.stream)this.stream.getAudioTracks().forEach(t=>t.enabled=false);this.talking=false;clearTimeout(this.talkTimer)}
 stopListening(){this.listening=false;clearTimeout(this.listenTimer);this.rec?.abort();this.rec=null}
 startListening(){if(this.connected){this.notify('Déconnectez l’IA avant d’activer les commandes du navigateur.');return}const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){this.notify('Commandes vocales indisponibles : utilisez Chrome / Edge ou les raccourcis.');return}this.stopListening();const r=new R();this.rec=r;r.lang='fr-FR';r.continuous=true;r.interimResults=false;this.listening=true;this.text('Micro actif · commandes uniquement · arrêt automatique après 10 minutes.');r.onresult=e=>{for(let i=e.resultIndex;i<e.results.length;i++){const t=e.results[i][0].transcript;this.text(t);const c=parseCommand(t);if(c?.action==='question'){this.notify('Question entendue. Utilisez le contexte ChatGPT ou connectez l’API.')}else if(c)this.command(c.action)}};r.onerror=e=>{if(e.error!=='aborted')this.notify('Micro interrompu : '+e.error);this.stopListening()};r.onend=()=>{this.listening=false;this.notify('Micro coupé. Réactivez-le si nécessaire.')};r.start();this.listenTimer=setTimeout(()=>this.stopListening(),600000);this.notify('Micro actif. Dites « Trame, suivante ».')}
 send(e){if(this.dc?.readyState==='open')this.dc.send(JSON.stringify(e))}
 async connect(endpoint,access){this.disconnect();this.stopListening();const u=new URL(endpoint||location.origin);if(u.protocol!=='https:'&&!['localhost','127.0.0.1'].includes(u.hostname))throw Error('Le serveur distant doit utiliser HTTPS.');this.endpoint=u.origin;try{this.stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});this.stream.getAudioTracks().forEach(t=>t.enabled=false);this.pc=new RTCPeerConnection();this.audio=new Audio();this.audio.autoplay=true;this.pc.ontrack=e=>{this.audio.srcObject=e.streams[0];this.audio.play().catch(()=>this.notify('Cliquez sur Parler pour autoriser la sortie audio.'))};this.stream.getTracks().forEach(t=>this.pc.addTrack(t,this.stream));this.dc=this.pc.createDataChannel('oai-events');this.dc.onmessage=e=>{const d=JSON.parse(e.data);if(d.type==='response.output_audio_transcript.done')this.text(d.transcript);if(d.type==='error')this.notify(d.error?.message||'Erreur de la session IA.')};const offer=await this.pc.createOffer();await this.pc.setLocalDescription(offer);const res=await fetch(this.endpoint+'/api/session',{method:'POST',headers:{'Content-Type':'application/sdp',...(access?{'Authorization':'Bearer '+access}:{})},body:offer.sdp});if(!res.ok)throw Error((await res.text()).slice(0,250));await this.pc.setRemoteDescription({type:'answer',sdp:await res.text()});this.connected=true;this.questions=0;this.sessionTimer=setTimeout(()=>{this.disconnect();this.notify('Session de 10 minutes terminée. Reconnectez volontairement si besoin.')},600000);this.pc.onconnectionstatechange=()=>{if(['failed','disconnected'].includes(this.pc?.connectionState)){this.disconnect();this.notify('Connexion IA perdue. Le cours reste disponible.')}};this.notify('IA connectée. Micro coupé ; cliquez sur Parler pour une question.')}catch(e){this.disconnect();throw e}}
 ask(text){if(!this.connected||!text.trim())return;if(++this.questions>30){this.disconnect();this.notify('Limite de 30 demandes atteinte.');return}this.stop();this.send({type:'conversation.item.create',item:{type:'message',role:'user',content:[{type:'input_text',text:this.context()+'\nQuestion : '+text.slice(0,2000)}]}});this.send({type:'response.create'});this.text('Réponse IA en cours…')}
 toggleTalk(){if(!this.connected)return;if(this.talking){this.stream.getAudioTracks().forEach(t=>t.enabled=false);this.talking=false;clearTimeout(this.talkTimer);this.send({type:'input_audio_buffer.commit'});this.send({type:'response.create',response:{instructions:'Contexte pédagogique : '+this.context()+'. Réponds brièvement à la question audio, en français, adapté aux adolescents. Ne demande aucune donnée personnelle.'}});this.text('Micro coupé · réponse en cours.')}else{if(++this.questions>30){this.disconnect();return}this.stop();this.audio?.play().catch(()=>{});this.send({type:'input_audio_buffer.clear'});this.stream.getAudioTracks().forEach(t=>t.enabled=true);this.talking=true;this.text('Micro actif · cliquez encore pour terminer (20 secondes maximum).');this.talkTimer=setTimeout(()=>this.toggleTalk(),20000)}}
 disconnect(){clearTimeout(this.sessionTimer);clearTimeout(this.talkTimer);this.stopListening();this.connected=false;this.talking=false;this.dc?.close();this.pc?.close();this.pc=null;this.stream?.getTracks().forEach(t=>t.stop());this.stream=null;if(this.audio){this.audio.pause();this.audio.srcObject=null}this.dc=null}
}
